import pandas as pd
from sklearn.preprocessing import StandardScaler

def task_func(df):
    required_cols = {"id", "age", "income"}
    missing_cols = required_cols - set(df.columns)
    if missing_cols:
        raise ValueError("DataFrame must contain 'id', 'age', and 'income' columns.")

    result = df.copy()

    for col in ["age", "income"]:
        result[col] = result.groupby("id")[col].transform(
            lambda s: StandardScaler().fit_transform(s.to_numpy().reshape(-1, 1)).ravel()
        )

    return result
